import datetime
from datetime import timedelta
import functools

_DAYS_IN_MONTH = (0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)
_MAX_YEAR = 3000


def _is_leap(year):
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)


_DIM = [[0] * 13 for _ in range(_MAX_YEAR + 1)]
_FIRST_DOW = [[0] * 13 for _ in range(_MAX_YEAR + 1)]
for _y in range(1, _MAX_YEAR + 1):
    _leap = _is_leap(_y)
    _dim_row = _DIM[_y]
    _dow_row = _FIRST_DOW[_y]
    for _m in range(1, 13):
        _dim_row[_m] = 29 if _m == 2 and _leap else _DAYS_IN_MONTH[_m]
        _dow_row[_m] = (datetime.date(_y, _m, 1).weekday() + 1) % 7

_VALID_DAY_MASK = [0] * 32
for _d in range(1, 32):
    _VALID_DAY_MASK[_d] = (1 << (_d + 1)) - 2

_DOW_PRE = []
for _first in range(7):
    _table = []
    for _days in range(32):
        _weekday_masks = [0] * 7
        _w = _first
        for _d in range(1, _days + 1):
            _weekday_masks[_w] |= 1 << _d
            _w = (_w + 1) % 7
        _arr = [0] * 128
        for _mask in range(1, 128):
            _lsb = _mask & -_mask
            _w = _lsb.bit_length() - 1
            _arr[_mask] = _arr[_mask ^ _lsb] | _weekday_masks[_w]
        _table.append(_arr)
    _DOW_PRE.append(_table)

_DIGITS = frozenset("0123456789")


def _is_digits(s):
    if not s:
        return False
    for ch in s:
        if ch not in _DIGITS:
            return False
    return True


def _all_mask(low, high):
    if low == 0 and high == 7:
        return (1 << 7) - 1
    if low == 0:
        return (1 << (high + 1)) - 1
    return ((1 << (high + 1)) - 1) ^ ((1 << low) - 1)


def _parse_field(field, low, high):
    if field == "*":
        return _all_mask(low, high)

    mask = 0
    for item in field.split(","):
        if not item:
            raise ValueError("empty cron item")

        if item == "*":
            mask |= _all_mask(low, high)
            continue

        step = 1
        if "/" in item:
            base, _, step_s = item.partition("/")
            if not _is_digits(step_s) or int(step_s) < 1:
                raise ValueError("bad cron step")
            step = int(step_s)

            if base == "*":
                start, end = low, high
            else:
                if "-" not in base:
                    raise ValueError("bad cron range")
                a, _, b = base.partition("-")
                if not _is_digits(a) or not _is_digits(b):
                    raise ValueError("bad cron range")
                start, end = int(a), int(b)
                if start < low or start > high or end < low or end > high:
                    raise ValueError("cron value out of range")
                if start > end:
                    raise ValueError("cron range start greater than end")
        else:
            if "-" in item:
                a, _, b = item.partition("-")
                if not _is_digits(a) or not _is_digits(b):
                    raise ValueError("bad cron range")
                start, end = int(a), int(b)
                if start < low or start > high or end < low or end > high:
                    raise ValueError("cron value out of range")
                if start > end:
                    raise ValueError("cron range start greater than end")
            else:
                if not _is_digits(item):
                    raise ValueError("bad cron value")
                start = end = int(item)
                if start < low or start > high:
                    raise ValueError("cron value out of range")

        if low == 0 and high == 7:
            for v in range(start, end + 1, step):
                if v == 7:
                    mask |= 1
                else:
                    mask |= 1 << v
        else:
            for v in range(start, end + 1, step):
                mask |= 1 << v

    return mask


@functools.lru_cache(maxsize=None)
def _parse_expr(expr):
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("cron expression must have five fields")

    minute_s, hour_s, dom_s, month_s, dow_s = fields

    minute_mask = _parse_field(minute_s, 0, 59)
    hour_mask = _parse_field(hour_s, 0, 23)
    dom_mask = _parse_field(dom_s, 1, 31)
    month_mask = _parse_field(month_s, 1, 12)
    dow_mask = _parse_field(dow_s, 0, 7)

    if not month_mask:
        raise ValueError("cron expression can never fire")

    dom_star = dom_s == "*"
    dow_star = dow_s == "*"

    possible = False
    mm = month_mask
    while mm:
        lsb = mm & -mm
        m = lsb.bit_length() - 1
        mm ^= lsb

        max_days = 29 if m == 2 else _DAYS_IN_MONTH[m]
        valid = _VALID_DAY_MASK[max_days]

        if dom_star and dow_star:
            possible = True
            break
        if dom_star:
            if dow_mask:
                possible = True
                break
        elif dow_star:
            if dom_mask & valid:
                possible = True
                break
        else:
            if dow_mask or (dom_mask & valid):
                possible = True
                break

    if not possible:
        raise ValueError("cron expression can never fire")

    min_low = (minute_mask & -minute_mask).bit_length() - 1
    first_hour = (hour_mask & -hour_mask).bit_length() - 1

    minute_ge = [0] * 60
    for m in range(60):
        mm = minute_mask & ~((1 << m) - 1)
        if mm:
            minute_ge[m] = (mm & -mm).bit_length() - 1
        else:
            minute_ge[m] = -1

    next_hour = [-1] * 24
    for h in range(24):
        hm = hour_mask & ~((1 << (h + 1)) - 1)
        if hm:
            next_hour[h] = (hm & -hm).bit_length() - 1

    first_month = (month_mask & -month_mask).bit_length() - 1
    month_ge = [0] * 13
    for m in range(1, 13):
        mm = month_mask & ~((1 << m) - 1)
        if mm:
            month_ge[m] = (mm & -mm).bit_length() - 1

    return (
        minute_mask,
        hour_mask,
        dom_mask,
        month_mask,
        dow_mask,
        dom_star,
        dow_star,
        minute_ge,
        next_hour,
        first_hour,
        min_low,
        first_month,
        month_ge,
    )


def next_fire(expr: str, after: datetime.datetime) -> datetime.datetime:
    (
        _minute_mask,
        _hour_mask,
        dom_mask,
        _month_mask,
        dow_mask,
        dom_star,
        dow_star,
        minute_ge,
        next_hour,
        first_hour,
        min_low,
        first_month,
        month_ge,
    ) = _parse_expr(expr)

    start = after.replace(second=0, microsecond=0) + timedelta(minutes=1)

    year = start.year
    month = start.month
    start_year = year
    start_month = month
    start_day = start.day
    start_hour = start.hour
    start_minute = start.minute

    while True:
        m = month_ge[month]
        if m == 0:
            year += 1
            m = first_month

        if year > _MAX_YEAR:
            raise ValueError("cron expression can never fire")

        days = _DIM[year][m]
        first_dow = _FIRST_DOW[year][m]
        valid = _VALID_DAY_MASK[days]

        if dom_star:
            if dow_star:
                day_mask = valid
            else:
                day_mask = _DOW_PRE[first_dow][days][dow_mask]
        elif dow_star:
            day_mask = dom_mask & valid
        else:
            day_mask = (dom_mask & valid) | _DOW_PRE[first_dow][days][dow_mask]

        if not day_mask:
            year += m // 12
            month = m % 12 + 1
            continue

        if year == start_year and m == start_month:
            d_mask = day_mask & ~((1 << start_day) - 1)
        else:
            d_mask = day_mask

        if not d_mask:
            year += m // 12
            month = m % 12 + 1
            continue

        d = (d_mask & -d_mask).bit_length() - 1

        if year == start_year and m == start_month and d == start_day:
            if _hour_mask & (1 << start_hour):
                minute = minute_ge[start_minute]
                if minute != -1:
                    return datetime.datetime(year, m, d, start_hour, minute)

            hour = next_hour[start_hour]
            if hour != -1:
                return datetime.datetime(year, m, d, hour, min_low)

            d_mask = d_mask & ~((1 << (d + 1)) - 1)
            if d_mask:
                d2 = (d_mask & -d_mask).bit_length() - 1
                return datetime.datetime(year, m, d2, first_hour, min_low)

            year += m // 12
            month = m % 12 + 1
        else:
            return datetime.datetime(year, m, d, first_hour, min_low)
